if($_SERVER['REQUEST_METHOD']==='POST')try{
 checkcsrf();$a=(string)($_POST['action']??'');
 if($a==='login'){
  throttle('login',10);$email=field('email',190);$pass=field('password',200);$user=q('SELECT * FROM sc_users WHERE email=? AND active=1',[$email])->fetch();
  if(!$user||!password_verify($pass,$user['password']))throw new RuntimeException('Credenciales incorrectas.');
  session_regenerate_id(true);$_SESSION['uid']=$user['id'];$_SESSION['last']=time();audit('inicio_sesion');go('admin');
 }elseif($a==='logout'){session_unset();session_destroy();go('home');
 }elseif($a==='case'){
  throttle('case',8);if(!empty($_POST['website']))throw new RuntimeException('No se pudo enviar.');
  $kind=field('kind',20);if(!in_array($kind,['convivencia','consulta','karin'],true))throw new RuntimeException('Tipo inválido.');
  if($kind==='karin'&&setting('karin_enabled')!=='1')throw new RuntimeException('Canal Karin no habilitado. Utiliza la orientación de la Dirección del Trabajo.');
  $name=field('name',160);$email=field('email',190);$unit=field('unit',80,false);$body=field('body',12000);
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($body)<15||empty($_POST['consent']))throw new RuntimeException('Revisa el correo, describe los hechos y acepta el aviso de privacidad.');
  $secret=bin2hex(random_bytes(16));$folio='SC-'.strtoupper(bin2hex(random_bytes(6)));
  q('INSERT INTO sc_cases(folio,secret_hash,kind,name,email,unit,body,consent_version,consent_text) VALUES (?,?,?,?,?,?,?,?,?)',[$folio,hash('sha256',$secret),$kind,$name,$email,$unit,$body,substr(hash('sha256',setting('privacy')),0,24),setting('privacy')]);
  $_SESSION['receipt']=['folio'=>$folio,'secret'=>$secret];go('recibida');
 }elseif($a==='track'){
  throttle('track',20);$folio=field('folio',30);$secret=field('secret',64);
  $tracking=q('SELECT folio,status,response,updated_at FROM sc_cases WHERE folio=? AND secret_hash=?',[$folio,hash('sha256',$secret)])->fetch();if(!$tracking)throw new RuntimeException('Folio o clave incorrectos.');
 }elseif($a==='settings'){
  need('admin');foreach(['name','address','headline','intro','contact','privacy','karin_contact'] as $key){$value=field($key,5000);q('UPDATE sc_settings SET value=? WHERE name=?',[$value,$key]);}
  $enabled=isset($_POST['karin_enabled'])?'1':'0';if($enabled==='1'&&!(int)q("SELECT COUNT(*) FROM sc_users WHERE role='karin' AND active=1")->fetchColumn())throw new RuntimeException('Crea primero una cuenta para el encargado Karin.');
  q('UPDATE sc_settings SET value=? WHERE name=?',[$enabled,'karin_enabled']);$pic=picture();if($pic)q('UPDATE sc_settings SET value=? WHERE name=?',[$pic,'hero']);audit('configuracion');$success='Configuración guardada.';
 }elseif($a==='content'){
  need('admin');$id=(int)($_POST['id']??0);$kind=field('kind',20);if(!in_array($kind,['section','news','faq','law','gallery','karin'],true))throw new RuntimeException('Sección inválida.');
  $title=field('title',200);$body=field('body',20000);$link=field('link',500,false);if($link!==''&&(!filter_var($link,FILTER_VALIDATE_URL)||parse_url($link,PHP_URL_SCHEME)!=='https'))throw new RuntimeException('El enlace debe ser una URL HTTPS válida.');
  $old=$id?q('SELECT * FROM sc_content WHERE id=?',[$id])->fetch():null;$pic=picture();$pic=$pic?:($old['image']??'');$pub=isset($_POST['published'])?1:0;
  if($id)q('UPDATE sc_content SET kind=?,title=?,body=?,image=?,link=?,published=? WHERE id=?',[$kind,$title,$body,$pic,$link,$pub,$id]);else q('INSERT INTO sc_content(kind,title,body,image,link,published) VALUES (?,?,?,?,?,?)',[$kind,$title,$body,$pic,$link,$pub]);audit('contenido_guardado',$id);go('admin&tab=content');
 }elseif($a==='delete_content'){
  need('admin');q('DELETE FROM sc_content WHERE id=?',[(int)$_POST['id']]);audit('contenido_eliminado',(int)$_POST['id']);go('admin&tab=content');
 }elseif($a==='case_update'){
  $user=need();$case=q('SELECT * FROM sc_cases WHERE id=?',[(int)$_POST['id']])->fetch();if(!$case||($case['kind']==='karin'? $user['role']!=='karin':$user['role']!=='admin'))throw new RuntimeException('Acceso no autorizado.');
  $status=field('status',30);if(!in_array($status,['Recibida','En revisión','Respondida','Cerrada'],true))throw new RuntimeException('Estado inválido.');
  q('UPDATE sc_cases SET status=?,response=? WHERE id=?',[$status,field('response',12000,false),$case['id']]);audit('caso_actualizado',$case['id']);$success='Estado y respuesta guardados.';
 }elseif($a==='delete_case'){
  $user=need();$case=q('SELECT id,kind FROM sc_cases WHERE id=?',[(int)$_POST['id']])->fetch();
  if(!$case||($case['kind']==='karin'?$user['role']!=='karin':$user['role']!=='admin')||empty($_POST['confirm']))throw new RuntimeException('Eliminación no autorizada o sin confirmar.');
  audit('caso_eliminado',$case['id']);q('DELETE FROM sc_cases WHERE id=?',[$case['id']]);go('admin');
 }elseif($a==='user'){
  need('admin');$email=field('email',190);$pass=field('password',200);$role=field('role',20);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12||!in_array($role,['admin','karin'],true))throw new RuntimeException('Revisa los datos de la cuenta.');
  q('INSERT INTO sc_users(email,password,role) VALUES (?,?,?)',[$email,password_hash($pass,PASSWORD_DEFAULT),$role]);audit('usuario_creado');$success='Cuenta creada.';
 }elseif($a==='disable_user'){
  $user=need('admin');$id=(int)$_POST['id'];if($id===$user['id'])throw new RuntimeException('No puedes desactivar tu propia cuenta.');q('UPDATE sc_users SET active=0 WHERE id=?',[$id]);if(!(int)q("SELECT COUNT(*) FROM sc_users WHERE role='karin' AND active=1")->fetchColumn())q("UPDATE sc_settings SET value='0' WHERE name='karin_enabled'");audit('usuario_desactivado',$id);$success='Cuenta desactivada.';
 }elseif($a==='password'){
  $user=need();$old=field('old',200);$new=field('password',200);$hash=q('SELECT password FROM sc_users WHERE id=?',[$user['id']])->fetchColumn();if(!password_verify($old,$hash)||strlen($new)<12)throw new RuntimeException('Contraseña actual incorrecta o nueva menor a 12 caracteres.');q('UPDATE sc_users SET password=? WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$user['id']]);session_regenerate_id(true);audit('password_actualizada');$success='Contraseña actualizada.';
 }
}catch(Throwable $ex){$error=$ex instanceof RuntimeException&&!($ex instanceof PDOException)?$ex->getMessage():'No se pudo guardar. Revisa los datos o intenta nuevamente.';error_log('Condominio: '.$ex->getMessage());}
if($p==='recibida'){$receipt=$_SESSION['receipt']??null;unset($_SESSION['receipt']);}
$u=me();$name=setting('name');
function content(string $kind):array{return q('SELECT * FROM sc_content WHERE kind=? AND published=1 ORDER BY id DESC',[$kind])->fetchAll();}
function formstart(string $action):void{echo '<form method="post" enctype="multipart/form-data">';csrf();echo '<input type="hidden" name="action" value="'.e($action).'">';}
function input(string $label,string $key,string $value='',string $type='text',bool $required=true):void{echo '<label>'.e($label).'<input type="'.e($type).'" name="'.e($key).'" value="'.e($value).'" '.($required?'required':'').'></label>';}
function area(string $label,string $key,string $value=''):void{echo '<label>'.e($label).'<textarea name="'.e($key).'" rows="5" required>'.e($value).'</textarea></label>';}
function cards(array $rows):void{foreach($rows as $r){echo '<article class="card">';if($r['image'])echo '<img loading="lazy" src="'.e($r['image']).'" alt="'.e($r['title']).'">';echo '<div class="card-body"><h3>'.e($r['title']).'</h3><p class="text">'.nl2br(e($r['body'])).'</p>';if($r['link'])echo '<a class="text-link" href="'.e($r['link']).'" target="_blank" rel="noopener noreferrer">Consultar documento ↗</a>';echo '</div></article>';}}
