dy></table></div><?php if(!$rows)echo '<p class="empty">No hay solicitudes recibidas.</p>';if($page>1)echo '<a href="?p=admin&page='.($page-1).'">← Anterior</a> ';if(count($rows)>30)echo '<a href="?p=admin&page='.($page+1).'">Siguiente →</a>';}
